package glitch

import data.glitch_lib

# Weak cryptographic algorithms and patterns
weak_algorithms := {"des", "3des", "rc4", "rc2", "blowfish", "md5", "md2", "md4", "sha-0", "sha-1", "sha1", "ripemd-160", "dsa", "ecdsa"}

weak_tls_versions := {"sslv2", "sslv3", "tlsv1.0", "tlsv1.1", "tls1.0", "tls1.1", "1.0", "1.1"}

insecure_modes := {"ecb", "none", "disabled", "false", "optional"}

weak_key_sizes := {512, 1024}

crypto_attr_names := {"encryption_algorithm", "cipher", "crypto_type", "hash_algorithm", "digest_algorithm", "ssl_policy", "tls_version", "protocol_version", "key_algorithm", "signing_algorithm", "certificate_algorithm", "kms_key_spec", "key_spec", "key_type", "block_cipher_mode", "sse_algorithm", "security_policy", "minimum_protocol_version", "mfa_configuration", "password_policy"}

dangerous_keywords := {"obfuscation", "encoding", "scramble", "base64", "hex", "rot13", "xor", "custom_crypto", "proprietary_encryption", "homegrown_cipher", "deprecated", "legacy", "compatibility_mode", "enable_weak_ciphers", "insecure_skip_verify", "insecure"}

# Helper to check if a string contains weak algorithm reference
contains_weak_algorithm(str) {
    lower_str := lower(str)
    alg := weak_algorithms[_]
    regex.match(sprintf(".*\\b%s\\b.*", [alg]), lower_str)
}

# Helper to check if a string contains weak TLS version
contains_weak_tls(str) {
    lower_str := lower(str)
    ver := weak_tls_vversions[_]
    regex.match(sprintf(".*\\b%s\\b.*", [ver]), lower_str)
}

# Helper to check if a string contains insecure mode
contains_insecure_mode(str) {
    lower_str := lower(str)
    mode := insecure_modes[_]
    regex.match(sprintf(".*\\b%s\\b.*", [mode]), lower_str)
}

# Helper to extract string value from various types
get_string_value(node) = value {
    node.ir_type == "String"
    value := node.value
} else = value {
    node.ir_type == "VariableReference"
    value := node.value
}

# Check for weak algorithm in attribute value
check_weak_crypto_value(node) {
    str := get_string_value(node)
    contains_weak_algorithm(str)
} else {
    str := get_string_value(node)
    contains_weak_tls(str)
} else {
    str := get_string_value(node)
    contains_insecure_mode(str)
} else {
    str := get_string_value(node)
    kw := dangerous_keywords[_]
    regex.match(sprintf(".*\\b%s\\b.*", [kw]), lower(str))
}

# Check for weak key size in integer value
check_weak_key_size(node) {
    node.ir_type == "Integer"
    weak_key_sizes[node.value]
}

# Recursively check Hash values for weak crypto
check_hash_recursive(node) {
    node.ir_type == "Hash"
    entry := node.value[_]
    check_weak_crypto_value(entry)
} else {
    node.ir_type == "Hash"
    entry := node.value[_]
    check_hash_recursive(entry)
}

# Check Array values recursively
check_array_recursive(node) {
    node.ir_type == "Array"
    elem := node.value[_]
    check_weak_crypto_value(elem)
} else {
    node.ir_type == "Array"
    elem := node.value[_]
    check_hash_recursive(elem)
} else {
    node.ir_type == "Array"
    elem := node.value[_]
    check_array_recursive(elem)
}

# Main check for weak crypto in attribute value
has_weak_crypto(node) {
    check_weak_crypto_value(node)
} else {
    check_weak_key_size(node)
} else {
    check_hash_recursive(node)
} else {
    check_array_recursive(node)
}

